begin;create extension if not exists pgtap with schema extensions;select plan(18);
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at)values
('00000000-0000-0000-0000-000000000000','99900000-0000-4000-8000-000000000050','authenticated','authenticated','advisor-owner@example.test','',now(),now(),now()),
('00000000-0000-0000-0000-000000000000','99900000-0000-4000-8000-000000000051','authenticated','authenticated','advisor-outsider@example.test','',now(),now(),now());
set local role authenticated;select set_config('request.jwt.claim.sub','99900000-0000-4000-8000-000000000050',true);select set_config('request.jwt.claims','{"sub":"99900000-0000-4000-8000-000000000050","role":"authenticated"}',true);
select public.create_business('advisor-test','Advisor Test Inc','Advisor Test','sole_proprietorship','retail','{"city":"Manila"}');select set_config('test.advisor_org',(select id::text from public.organizations where slug='advisor-test'),true);select set_config('test.advisor_branch',(select id::text from public.branches where organization_id=current_setting('test.advisor_org')::uuid),true);select set_config('test.advisor_version',(select version.id::text from public.business_os_template_versions version join public.business_os_templates template on template.id=version.template_id where template.key='retail-store-os'and version.status='published'order by version.version desc limit 1),true);select public.install_business_os_template(current_setting('test.advisor_org')::uuid,current_setting('test.advisor_version')::uuid);select public.set_business_module_state(current_setting('test.advisor_org')::uuid,'product_catalog',true,'{}');select public.set_business_module_state(current_setting('test.advisor_org')::uuid,'inventory',true,'{}');
select set_config('test.advisor_location',(select id::text from public.inventory_locations where organization_id=current_setting('test.advisor_org')::uuid),true);select set_config('test.advisor_product',public.save_catalog_product(current_setting('test.advisor_org')::uuid,null,null,'product','Advisor Wrench','',null,null,'piece',100,60,'exclusive',0,'active',false,'[{"name":"Default","sku":"ADV-1","attributes":{},"status":"active"}]','[]')::text,true);select set_config('test.advisor_variant',(select id::text from public.product_variants where product_id=current_setting('test.advisor_product')::uuid),true);select set_config('test.advisor_item',public.configure_inventory_item(current_setting('test.advisor_org')::uuid,null,current_setting('test.advisor_variant')::uuid,3,5,true)::text,true);select public.record_stock_movement(current_setting('test.advisor_org')::uuid,current_setting('test.advisor_item')::uuid,current_setting('test.advisor_location')::uuid,'opening_balance',4,60,'Opening','advisor-opening-1');
reset role;insert into public.sales_customers(organization_id,branch_id,name,phone,transaction_count,total_spend,last_transaction_at)values(current_setting('test.advisor_org')::uuid,current_setting('test.advisor_branch')::uuid,'Dormant Customer','+639171234567',1,100,now()-interval'45 days');
set local role authenticated;select set_config('request.jwt.claim.sub','99900000-0000-4000-8000-000000000050',true);select set_config('request.jwt.claims','{"sub":"99900000-0000-4000-8000-000000000050","role":"authenticated"}',true);
select results_eq($$select count(*)from public.advisor_business_query_definitions where is_enabled$$,$$select 3::bigint$$,'Approved query registry contains only bounded advisor queries');
select is((public.query_advisor_business_data(current_setting('test.advisor_org')::uuid,'reorder_candidates')#>>'{rows,0,productName}'),'Advisor Wrench','Reorder query returns source-backed inventory candidates');
select is((public.query_advisor_business_data(current_setting('test.advisor_org')::uuid,'reorder_candidates')#>>'{rows,0,suggestedQuantity}')::numeric,1::numeric,'Suggested quantity only fills the configured target');
select is((public.query_advisor_business_data(current_setting('test.advisor_org')::uuid,'customers_not_returned')#>>'{rows,0,name}'),'Dormant Customer','Customer return query uses recorded last purchase');
select is((public.query_advisor_business_data(current_setting('test.advisor_org')::uuid,'product_sales_comparison')#>'{rows}'),'[]'::jsonb,'Comparison query reports an empty factual result without inventing products');
select throws_ok($$select public.query_advisor_business_data(current_setting('test.advisor_org')::uuid,'raw_customers')$$,'22023','Unknown or unavailable business query.','Arbitrary business queries are rejected');
select throws_ok($$select public.query_advisor_business_data(current_setting('test.advisor_org')::uuid,'reorder_candidates',current_date-7,current_date)$$,'22023','This business query is a current snapshot and does not accept date filters.','Snapshot query rejects misleading dates');
select set_config('test.advisor_conversation',public.start_ai_advisor_conversation(current_setting('test.advisor_org')::uuid,null)::text,true);
select results_eq($$select role from public.ai_advisor_messages where conversation_id=current_setting('test.advisor_conversation')::uuid$$,$$select 'assistant'::text$$,'Conversation begins with a bounded-data disclosure');
select lives_ok($$select public.record_ai_advisor_exchange(current_setting('test.advisor_org')::uuid,current_setting('test.advisor_conversation')::uuid,'What should I reorder?','Reorder result','{"sections":[{"kind":"recommendation","title":"Reorder","content":"One item","evidence":[]}],"insufficientData":false,"followUpQuestions":["What is low stock?"]}','[{"metricKey":"low_stock_count","value":1}]','[{"queryKey":"reorder_candidates","rows":[{"sku":"ADV-1"}]}]','answered',array['low_stock_count'],array['reorder_candidates'])$$,'Validated advisor exchange is stored atomically');
select results_eq($$select role from public.ai_advisor_messages where conversation_id=current_setting('test.advisor_conversation')::uuid order by created_at,id$$,$$select role from (values('assistant'::text),('user'::text),('assistant'::text)) as expected(role)$$,'Conversation preserves user and assistant order');
select is((select metric_evidence#>>'{0,metricKey}'from public.ai_advisor_messages where conversation_id=current_setting('test.advisor_conversation')::uuid and role='assistant'order by created_at desc limit 1),'low_stock_count','Exact metric evidence is retained');
select is((select business_query_evidence#>>'{0,queryKey}'from public.ai_advisor_messages where conversation_id=current_setting('test.advisor_conversation')::uuid and role='assistant'order by created_at desc limit 1),'reorder_candidates','Exact approved-query evidence is retained');
select results_eq($$select event,metric_keys,business_query_keys from public.ai_advisor_events where conversation_id=current_setting('test.advisor_conversation')::uuid order by created_at desc limit 1$$,$$select 'answered'::text,array['low_stock_count']::text[],array['reorder_candidates']::text[]$$,'Advisor query provenance is audited');
select is((select title from public.ai_advisor_conversations where id=current_setting('test.advisor_conversation')::uuid),'What should I reorder?','First question names the conversation');
select throws_ok($$insert into public.ai_advisor_messages(organization_id,conversation_id,role,content)values(current_setting('test.advisor_org')::uuid,current_setting('test.advisor_conversation')::uuid,'user','Bypass')$$,'42501','permission denied for table ai_advisor_messages','Clients cannot bypass the exchange RPC');
select set_config('request.jwt.claim.sub','99900000-0000-4000-8000-000000000051',true);select set_config('request.jwt.claims','{"sub":"99900000-0000-4000-8000-000000000051","role":"authenticated"}',true);
select results_eq($$select count(*)from public.ai_advisor_conversations where organization_id=current_setting('test.advisor_org')::uuid$$,$$select 0::bigint$$,'Another user cannot read the owner conversation');
select throws_ok($$select public.start_ai_advisor_conversation(current_setting('test.advisor_org')::uuid,null)$$,'42501','Permission denied.','Non-members cannot start tenant conversations');
select throws_ok($$select public.record_ai_advisor_exchange(current_setting('test.advisor_org')::uuid,current_setting('test.advisor_conversation')::uuid,'Steal data','No','{"sections":[],"followUpQuestions":[]}','[]','[]','answered','{}','{}')$$,'42501','Permission denied.','Another user cannot append to the conversation');
select *from finish();rollback;
